import{_ as t,o as r,c as e,a8 as n}from"./chunks/framework.BWjTbCIc.js";const u=JSON.parse('{"title":"港大同学会书院 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-28724523","school_zh":"港大同学会书院","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"港大同学会书院 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["HKUGA-S1-HIST-BRIDGE","HOT22-HKUGA"],"rounds":["r1","r2","r3"]},"headers":[],"relativePath":"reports/school-28724523/s1/unknown-interview.md","filePath":"reports/school-28724523/s1/unknown-interview.md"}'),s={name:"reports/school-28724523/s1/unknown-interview.md"};function a(p,o,l,g,c,h){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="港大同学会书院-·-年份未注明-·-中一-·-面试" tabindex="-1">港大同学会书院 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#港大同学会书院-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;港大同学会书院 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-28724523">← 返回港大同学会书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-hkuga-s1-hist-bridge" tabindex="-1">资料来源：港大同學會書院中一入学考情总结.pdf <a class="header-anchor" href="#record-hkuga-s1-hist-bridge" aria-label="Permalink to &quot;资料来源：港大同學會書院中一入学考情总结.pdf {#record-hkuga-s1-hist-bridge}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构历史面试整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>个人及小组形式</strong></p><p>约两位老师面见十位学生，包含个人与小组环节。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语／普通话</p><p><strong>情景表达</strong></p><p>以一种动物形容家长；希望拥有哪种超能力；讨论如何协助插班生适应新环境，以及朋友欺凌他人时应如何处理。</p><p><strong>新闻讨论</strong></p><p>阅读网购口罩受骗等新闻，表达感受与看法。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>情景卡与应对卡</strong></p><p>抽取情景卡和应对卡后论述观点，例如朋友不断炫耀成绩令你烦恼，配上“Angry, tell him not to do this”应对卡，解释自己的判断与处理方式。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>小组任务：</strong> 语言未注明</p><p><strong>合作搭桥</strong></p><p>4至5人一组，约60分钟。使用约100根小木棍及固定工具，搭建一座至少50厘米长、能够承重的桥。</p></blockquote><h3 id="第三轮-·-原文明示" tabindex="-1">第三轮 · 原文明示 <a class="header-anchor" href="#第三轮-·-原文明示" aria-label="Permalink to &quot;第三轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>学生面谈：</strong> 英语</p><p><strong>亲子面试</strong></p><p>学生与家长共同参与，约20分钟，与校长或副校长面谈。学生先作英文自我介绍，再回顾前两轮的任务、个人表现及可以改进之处。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>选校与家校合作</strong></p><p>选校原因、孩子升中后的期望、对家校合作的看法，以及希望进一步向学校了解的问题。</p></blockquote><h2 id="record-hot22-hkuga" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-hkuga" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-hkuga}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示-1" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示-1" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>朗读理解</strong></p><p>朗读文章并回答2题。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>图书卡片</strong></p><p>桌上4张印有图书的卡片，选一张介绍图书内容、喜欢原因和最喜欢的角色。</p><p><strong>当日感受</strong></p><p>今天做了什么，对本次面试有何感受。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 中文（口语未注明）</p><p><strong>人物与想象</strong></p><p>最想认识哪位名人或卡通人物，见面后会做什么；最欣赏哪位名人。</p></blockquote><h3 id="第二轮-·-原文明示-1" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示-1" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>个人档案与选校</strong></p><p>主要围绕个人档案追问；申请了哪些其他学校，最喜欢哪一所。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>升中适应</strong></p><p>是否担心孩子无法适应中学校园生活。</p></blockquote>',27)])])}const d=t(s,[["render",a]]);export{u as __pageData,d as default};
